using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.USR.TiposMascota;namespace GraphApi.Services.USR.TiposMascota{    public class TiposMascotaService : ITiposMascotaService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public TiposMascotaService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadTiposMascota>> GetTiposMascotas(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM usr.TiposMascota (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadTiposMascota>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetTiposMascotasDynamic(            int? tipoMascotaID,            string? tipoMascota,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "TipoMascotaID, TipoMascota, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM usr.TiposMascota (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (tipoMascotaID.HasValue)            {                vSql.Append(" AND TipoMascotaID = @TipoMascotaID");                vParameters.Add("TipoMascotaID",tipoMascotaID);            }            if (!string.IsNullOrWhiteSpace(tipoMascota))            {                vSql.Append(" AND TipoMascota LIKE @TipoMascota");                vParameters.Add("TipoMascota",$"%{tipoMascota}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadTiposMascota> CreateTiposMascota(clCreateTiposMascota objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO usr.TiposMascota                (TipoMascota, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TipoMascota, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TipoMascota,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT TipoMascotaID, TipoMascota, bEliminado                FROM usr.TiposMascota (NOLOCK)                WHERE TipoMascotaID = @TipoMascotaID;";            var vReadParams = new { TipoMascotaID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadTiposMascota>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el TiposMascota con ID {vNewId}.");            return vCreated;        }        public async Task<clReadTiposMascota?> UpdateTiposMascota(clUpdateTiposMascota objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("TipoMascotaID", objInput.TipoMascotaID);            if (objInput.TipoMascota is not null)            {                vSets.Add("TipoMascota = @TipoMascota");                vParameters.Add("TipoMascota", objInput.TipoMascota);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE usr.TiposMascota                SET {vSetClause}                WHERE TipoMascotaID = @TipoMascotaID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT TipoMascotaID, TipoMascota, bEliminado                FROM usr.TiposMascota (NOLOCK)                WHERE TipoMascotaID = @TipoMascotaID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadTiposMascota>(sSelect, new {  objInput.TipoMascotaID });        }        public async Task<bool> DeleteTiposMascota(int nTiposMascotaID)        {            const string sSql = @"                DELETE FROM usr.TiposMascota                WHERE TipoMascotaID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nTiposMascotaID });            return vAffected > 0;        }    }}